        // So we pick any address (e.g., address(0x1234)) as caddress.
        address from = address(0x1111);
        address caddress = address(0x2222);
        address[] memory tos = new address[](1);
        tos[0] = address(0x3333);
        uint v = 100;

        // Call transfer
        bool result = c.transfer(from, caddress, tos, v);
        // P returns true, M returns false
        assertTrue(result == true);
    }
}

